########## overrides/app/components/ui-kits/atoms/zimmProductPrice/index.tsx
     1	import React from 'react';
     2	import { chakra, useStyleConfig } from '@chakra-ui/react';
     3	
     4	const ZIMM_PRODUCT_PRICE_RECIPE = 'ZimmProductPrice';
     5	
     6	type ZimmProductPriceProps = {
     7	  /**
     8	   * The price, already formatted for the storefront's locale and currency by the caller
     9	   * (`intl.formatNumber` at the page). This atom does no formatting of its own so it stays
    10	   * usable from Storybook without an intl provider.
    11	   *
    12	   * Optional because the page's mapper resolves an absent price to `''` rather than to a
    13	   * formatted `NaN` — see `pages/product-detail/productInfo.ts`'s `selectPdpProductInfo` and
    14	   * the assertion it carries in `productInfo.test.ts`. That empty string reaches this atom
    15	   * unchanged and the decision not to render is taken here.
    16	   */
    17	  price?: string;
    18	  /** Reserved for SFCC-194's was/now treatment; only `default` is implemented today. */
    19	  variant?: 'default';
    20	};
    21	
    22	/**
    23	 * Atom — the single, full product price. Styling lives in `zimmProductPrice.css.ts` and is
    24	 * consumed through the theme, per the one-canonical-styling-surface rule.
    25	 *
    26	 * Renders nothing when there is no price, so a caller can place it unconditionally — the same
    27	 * contract as `ZimmProductDescription`. Rendering an empty `<p>` instead would still take a
    28	 * flex `gap` in `ZimmProductContent`'s column, leaving a hole where the price should be.
    29	 */
    30	export const ZimmProductPrice = ({ price, variant = 'default' }: ZimmProductPriceProps) => {
    31	  // Guard below the hook, never above it: an early return before `useStyleConfig` makes the
    32	  // hook call conditional, which `react-hooks/rules-of-hooks` reports as an error rather than a
    33	  // warning. Same ordering as `ZimmProductDescription` and `ZimmProductStyleCode`.
    34	  const styles = useStyleConfig(ZIMM_PRODUCT_PRICE_RECIPE, { variant });
    35	  if (!price) return null;
    36	
    37	  return (
    38	    <chakra.p __css={styles} textStyle="price" data-testid="product-price">
    39	      {price}
    40	    </chakra.p>
    41	  );
    42	};
########## overrides/app/components/ui-kits/atoms/zimmProductPrice/index.test.tsx
     1	/**
     2	 * Scoped to this atom's own contract per testing.md: given a formatted string or nothing, does
     3	 * it render the right branch.
     4	 *
     5	 * Formatting is deliberately not asserted here — it happens at the page
     6	 * (`selectPdpProductInfo`, proven in pages/product-detail/productInfo.test.ts) and this atom
     7	 * renders whatever string it is handed. What is not proven anywhere else is the absent branch:
     8	 * the mapper resolves a missing price to `''`, so the empty case is a real production path and
     9	 * not a defensive edge case.
    10	 */
    11	import React from 'react';
    12	import { describe, test, expect } from 'vitest';
    13	import { render, screen } from '@testing-library/react';
    14	import { ZimmProductPrice } from './index';
    15	
    16	describe('ZimmProductPrice', () => {
    17	  test('renders the caller-formatted string verbatim', () => {
    18	    render(<ZimmProductPrice price="HK$6,200.00" />);
    19	    // Verbatim, not re-formatted: the currency symbol, grouping and decimals are all the
    20	    // page's decisions, and re-deriving any of them here would diverge per storefront.
    21	    expect(screen.getByTestId('product-price').textContent).toBe('HK$6,200.00');
    22	  });
    23	
    24	  test.each([undefined, ''])('renders nothing for %s', (price) => {
    25	    render(<ZimmProductPrice price={price} />);
    26	    // `''` is what the page's mapper produces for a product with no price, so this branch is
    27	    // reached in production. An empty styled node would still consume a gap in
    28	    // ZimmProductContent's flex column, leaving a visible hole between name and description.
    29	    expect(screen.queryByTestId('product-price')).not.toBeInTheDocument();
    30	  });
    31	});
########## overrides/app/components/ui-kits/atoms/zimmProductPrice/zimmProductPrice.css.ts
     1	import type { SystemStyleObject } from '@chakra-ui/react';
     2	
     3	/**
     4	 * Recipe for the PDP price.
     5	 *
     6	 * The DS models `pdp/price` with two states, so this carries a `variants` map rather than a
     7	 * bare `baseStyle` — see .claude/rules/overrideStyling.md tier 3. Only `default` is populated:
     8	 * the was/now (sale) treatment belongs to SFCC-194, and its colours and strike-through are not
     9	 * specced anywhere we can read today. Adding a `sale` key that merely echoes `default` would
    10	 * look finished and be wrong, so the extension point is documented instead of stubbed.
    11	 *
    12	 * SFCC-194 adds `sale` alongside `default` below; nothing else in this file needs to change.
    13	 */
    14	export const ZimmProductPrice = {
    15	  baseStyle: {
    16	    margin: 0,
    17	    color: 'var(--zimm-color-text-default)',
    18	  } satisfies SystemStyleObject,
    19	
    20	  variants: {
    21	    default: {} satisfies SystemStyleObject,
    22	  },
    23	
    24	  defaultProps: {
    25	    variant: 'default',
    26	  },
    27	};

